const n=["fóda","fooda","phooda","phoda","porra","pqp","vtnc","punheta","masturbação","masturba","siririca","punheta","caralho","bosta","merda","foder","puta","bôzo","bozo","lulá","lula","bolsonaro","xoxota","xota","buceta","pirú","piru","piroca","cu","cú"],e={palavras:n};function i(a){return a.normalize("NFD").replace(new RegExp("\\p{Diacritic}","gu"),"").toLowerCase().replace(/\s+/g," ").trim()}function t(a){return a.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}const p=e.palavras.map(a=>({original:a,normalizada:i(a)})).filter(a=>a.normalizada!=="").map(a=>({original:a.original,regex:new RegExp(`(?<![\\p{L}\\p{N}])${t(a.normalizada)}(?![\\p{L}\\p{N}])`,"u")}));function l(a){const o=i(a);return o===""?[]:p.filter(r=>r.regex.test(o)).map(r=>r.original)}function s(a,o){if(o)return null;const r=l(a);return r.length>0?`Palavra proibida: ${r.join(", ")}. Remova para enviar.`:null}export{s as a,l as p};
